<!doctype html><html lang="fr" data-theme="dark"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Connexion — DVSSER</title><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Syne:wght@700;800&family=DM+Sans:wght@300;400;500&display=swap" rel="stylesheet"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css"><link rel="stylesheet" href="<?= base_url('assets/css/style.css') ?>"></head><body class="login-page"><div class="stars"></div><div class="stars2"></div><button class="theme-toggle-login" id="themeBtn" title="Changer le thème"><i class="bi bi-moon-stars" id="themeIcon"></i></button><div class="login-wrap"><div class="login-card"><div class="login-logo"><img src="<?= base_url('assets/images/icone1.png') ?>" alt="DVSSER"><span class="app-name">DVSSER</span><span class="app-sub">Surveillance au niveau pharmacie<br>Ministère de la Santé Publique de Madagascar</span></div><?php if(session('error')): ?><div class="error-msg"><i class="bi bi-exclamation-triangle"></i><?= esc(session('error')) ?></div><?php endif; ?><form method="post" action="<?= site_url('connexion') ?>"><?= csrf_field() ?><div class="form-group"><label class="form-label" for="username">Nom d'utilisateur</label><input id="username" name="username" class="form-input" value="<?= esc(old('username')) ?>" placeholder="Entrez votre identifiant" required autocomplete="username"></div><div class="form-group"><label class="form-label" for="password">Mot de passe</label><div class="password-box"><input type="password" id="password" name="password" class="form-input" placeholder="Entrez votre mot de passe" required autocomplete="current-password"><i class="fa-solid fa-eye" id="eyeIcon"></i></div></div><a href="#" class="forgot-link" id="forgotLink">Mot de passe oublié ?</a><button class="submit-btn"><i class="bi bi-box-arrow-in-right"></i> Se connecter</button></form></div><div class="login-footer">&copy;<span id="yr"></span> Ministère de la Santé Publique de Madagascar<br>Direction de la Veille Sanitaire, de la Surveillance Épidémiologique et Riposte</div></div><script>const h=document.documentElement,b=document.getElementById('themeBtn'),i=document.getElementById('themeIcon'),p=document.getElementById('password'),e=document.getElementById('eyeIcon');document.getElementById('yr').textContent=new Date().getFullYear();i.className='bi bi-sun';b.onclick=()=>{const n=h.dataset.theme==='dark'?'light':'dark';h.dataset.theme=n;i.className=n==='dark'?'bi bi-sun':'bi bi-moon-stars'};e.onclick=()=>{p.type=p.type==='password'?'text':'password';e.classList.toggle('fa-eye');e.classList.toggle('fa-eye-slash')};document.getElementById('forgotLink').onclick=()=>{alert('Veuillez contacter votre administrateur système : 034 03 887 72');return false}</script></body></html>
